class Graph:
    def __init__(self):
        # Store nodes and edges
        self.nodes_set = set()
        self.edges = {}

    def add_node(self, n):
        """Add a node to the graph."""
        self.nodes_set.add(n)

    def add_edge(self, a, b, weight=1):
        """Add an edge between nodes a and b with given weight."""
        # Check if weight is positive
        if weight <= 0:
            raise ValueError("Weight must be a positive number")

        # Add nodes if they don't exist
        self.add_node(a)
        self.add_node(b)

        # Add edge (replace if exists)
        if a not in self.edges:
            self.edges[a] = {}
        self.edges[a][b] = weight

    def nodes(self):
        """Return every node sorted."""
        return sorted(list(self.nodes_set))

    def neighbors(self, a):
        """Return a sorted list of (b, weight) tuples for neighbors of node a."""
        if a not in self.edges:
            return []

        # Return neighbors sorted by node name
        return sorted([(node, weight) for node, weight in self.edges[a].items()])

// Cache class implementation with LRU eviction
class Cache {
  constructor(capacity) {
    // Validate capacity
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }

    this.capacity = capacity;
    this.map = new Map();
  }

  set(key, value) {
    // If key exists, update it and move to end (most recently used)
    if (this.map.has(key)) {
      this.map.delete(key);
    }

    // Add new key-value pair
    this.map.set(key, value);

    // If cache is over capacity, remove the least recently used item
    if (this.map.size > this.capacity) {
      // Get the first key (least recently used) and delete it
      const firstKey = this.map.keys().next().value;
      this.map.delete(firstKey);
    }
  }

  get(key) {
    // If key doesn't exist, return undefined
    if (!this.map.has(key)) {
      return undefined;
    }

    // Get the value and move to end (mark as most recently used)
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);

    return value;
  }

  has(key) {
    return this.map.has(key);
  }

  size() {
    return this.map.size;
  }
}

module.exports = { Cache };

class Gradebook:
    def __init__(self):
        self.students = {}
        self.assignments = {}

    def add_student(self, name):
        if name in self.students:
            raise ValueError("Student already exists")
        self.students[name] = {}

    def add_assignment(self, name, max_points):
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        if not isinstance(max_points, (int, float)) or max_points <= 0:
            raise ValueError("Max points must be a positive number")
        self.assignments[name] = max_points

    def record(self, student, assignment, points):
        if student not in self.students:
            raise KeyError("Unknown student")
        if assignment not in self.assignments:
            raise KeyError("Unknown assignment")
        if not isinstance(points, (int, float)) or points < 0 or points > self.assignments[assignment]:
            raise ValueError("Points must be between 0 and max points")
        self.students[student][assignment] = points

    def score(self, student, assignment):
        if student not in self.students or assignment not in self.students[student]:
            return None
        return self.students[student][assignment]

