    }

    // Check for division by zero
    if (expr.includes('/0')) {
        throw new Error('Division by zero');
    }

    // Simple recursive descent parser for expressions with +, -, *, /, parentheses and unary minus
    function parseExpression() {
        let result = parseTerm();

        while (pos < expr.length) {
            if (expr[pos] === '+') {
                pos++;
                result += parseTerm();
            } else if (expr[pos] === '-') {
                pos++;
                result -= parseTerm();
            } else {
                break;
            }
        }

        return result;
    }

    function parseTerm() {
        let result = parseFactor();

        while (pos < expr.length) {
            if (expr[pos] === '*') {
                pos++;
                result *= parseFactor();
            } else if (expr[pos] === '/') {
                pos++;
                const divisor = parseFactor();
                if (divisor === 0) {
                    throw new Error('Division by zero');
                }
                result /= divisor;
            } else {
                break;
            }
        }

        return result;
    }

    function parseFactor() {
        if (pos >= expr.length) {
            throw new Error('Invalid expression');
        }

        let sign = 1;
        if (expr[pos] === '-') {
            sign = -1;
            pos++;
        } else if (expr[pos] === '+') {
            pos++;
        }

        let result;

        if (expr[pos] === '(') {
            pos++; // consume '('
            result = parseExpression();
            if (pos >= expr.length || expr[pos] !== ')') {
                throw new Error('Invalid parentheses');
            }
            pos++; // consume ')'
        } else if (/\d/.test(expr[pos])) {
            let start = pos;
            while (pos < expr.length && (/\d/.test(expr[pos]) || expr[pos] === '.')) {
                pos++;
            }
            result = parseFloat(expr.substring(start, pos));
        } else {
            throw new Error('Invalid expression');
        }

        return sign * result;
    }

    let pos = 0;
    try {
        const result = parseExpression();

        // Check if we parsed the entire expression
        if (pos !== expr.length) {
            throw new Error('Invalid expression');
        }

        // Check if result is a valid number
        if (typeof result !== 'number' || isNaN(result)) {
            throw new Error('Invalid expression');
        }

        return result;
    } catch (e) {
        if (e.message === 'Division by zero') {
            throw e;
        }
        throw new Error('Invalid expression');
    }
