        expr = expr.replace(/\*(_minus_)/, '*(-');
        expr = expr.replace(/\/(_minus_)/, '/(-');
        expr = expr.replace(/\+(_minus_)/, '+(-');
        expr = expr.replace(/\^(_minus_)/, '^(-');

