                    if (expr[i] === '(') {
                        if (parenCount === 0) start = i;
                        parenCount++;
                    } else if (expr[i] === ')') {
                        parenCount--;
                        if (parenCount === 0) {
                            // Found innermost parentheses
                            let innerExpr = expr.substring(start + 1, i);
                            let innerResult = parse(innerExpr);
