  for (let i = 0; i < keysBefore.length; i++) {
    if (keysBefore[i] !== keysAfter[i]) {
      console.error("FAIL: peek should not change key order");
      return false;
    }
  }

  console.log("PASS: peek method works correctly");
  return true;
}

