    if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
      throw new Error('n must be a positive integer');
    }

    const rows = [];
    for (let i = 0; i < n; i++) {
      const row = new Array(n).fill(0);
      row[i] = 1;
      rows.push(row);
    }

    return new Matrix(rows);
  }

