    this.map.set(key, entry);

    // If cache is over capacity, remove the least recently used item
    if (this.map.size > this.capacity) {
      // Get the first key (least recently used) and delete it
      const firstKey = this.map.keys().next().value;
      this.map.delete(firstKey);
    }
  }

  get(key) {
    // If key doesn't exist, return undefined
    if (!this.map.has(key)) {
      return undefined;
    }

    // Get the entry and check if it's expired
    const entry = this.map.get(key);
    if (this._isExpired(entry)) {
      this.map.delete(key);
      return undefined;
    }

    // Get the value and move to end (mark as most recently used)
    const value = entry.value;
    this.map.delete(key);
    this.map.set(key, entry);

    return value;
  }

  peek(key) {
    // If key doesn't exist, return undefined
    if (!this.map.has(key)) {
      return undefined;
    }

    // Get the entry and check if it's expired
    const entry = this.map.get(key);
    if (this._isExpired(entry)) {
      this.map.delete(key);
      return undefined;
    }

    // Get the value without updating usage order
    return entry.value;
  }

  has(key) {
    // If key doesn't exist, return false
    if (!this.map.has(key)) {
      return false;
    }

    // Get the entry and check if it's expired
    const entry = this.map.get(key);
    if (this._isExpired(entry)) {
      this.map.delete(key);
      return false;
    }

    return true;
  }

  size() {
    // Count non-expired entries
    let count = 0;
    for (const entry of this.map.values()) {
      if (!this._isExpired(entry)) {
        count++;
      }
    }
    return count;
  }

  delete(key) {
    return this.map.delete(key);
  }

  clear() {
    this.map.clear();
  }

  keys() {
    // Return keys in insertion order (not LRU order) but only for non-expired entries
    const result = [];
    for (const [key, entry] of this.map.entries()) {
      if (!this._isExpired(entry)) {
        result.push(key);
      }
    }
    return result;
  }

  _isExpired(entry) {
    if (entry.ttl === undefined) {
      return false;
    }
    return (this.now() - entry.timestamp) >= entry.ttl;
  }
}

